def validate_functions(expr: Any) -> None:
    """Validate function names and arity, even for empty result sets."""
    if expr is None:
        return
    for node in ast.walk(expr):
        if not isinstance(node, ast.Func):
            continue

        name = node.name.upper() if isinstance(node.name, str) else node.name
        if name not in AGGREGATE_NAMES and name not in _SCALAR_FUNCTIONS:
